mapper.select:
select h.hotelno, COALESCE(rh.realhotelname, h.hotelName) as realhotelName, COALESCE(h.hotelFileName, (select min(hi.hotelFileName) from hotel_image hi where hi.hotelNo = h.hotelNo) ) as hotelFileName, COALESCE(rh.state, h.mainAddress) as state, (select min(hr.roomPrice) from hotel_room hr where hr.hotelNo = h.hotelNo) as roomPrice, NVL(a.ag, 0) as ag, h.buffet, h.swim, h.golf, h.pet, h.restaurant, h.fitness, h.parking, h.wifi, h.kitchen, h.smoke from hotel h left join realhotel rh on h.realhotelno = rh.realhotelno left join ( select hotelno, round(avg(grade),1) as ag from review group by hotelno ) a on a.hotelno = h.hotelno
AND ( rh.state LIKE '%'||#{keyword}||'%' OR h.mainAddress LIKE '%'||#{keyword}||'%' OR h.hotelName LIKE '%'||#{keyword}||'%' )
AND EXISTS ( SELECT 1 FROM hotel_room hr WHERE hr.hotelNo = h.hotelNo AND NOT EXISTS ( SELECT 1 FROM reservation r WHERE r.roomNo = hr.roomNo AND r.checkInDate < TO_DATE(#{checkOut}, 'YYYY-MM-DD') AND r.checkOutDate > TO_DATE(#{checkIn}, 'YYYY-MM-DD') ) )
AND (
rh.state LIKE '%'||#{a}||'%'
)
AND EXISTS ( SELECT 1 FROM hotel_room hrp WHERE hrp.hotelNo = h.hotelNo AND REGEXP_LIKE(hrp.roomPrice, '^[0-9]+$')
AND TO_NUMBER(hrp.roomPrice) >= #{minPrice}
AND TO_NUMBER(hrp.roomPrice) <= #{maxPrice}
)
AND EXISTS ( SELECT 1 FROM hotel_room hrg WHERE hrg.hotelNo = h.hotelNo AND ( REGEXP_SUBSTR(hrg.bedNo, '^[0-9]+') IS NULL OR TO_NUMBER(REGEXP_SUBSTR(hrg.bedNo, '^[0-9]+')) >= #{guests} ) )
AND NVL(a.ag, 0) >= #{grade}
AND UPPER(h.buffet) = 'T' AND UPPER(h.swim) = 'T' AND UPPER(h.golf) = 'T' AND UPPER(h.pet) = 'T' AND UPPER(h.restaurant) = 'T' AND UPPER(h.fitness) = 'T' AND UPPER(h.parking) = 'T' AND UPPER(h.wifi) = 'T' AND UPPER(h.kitchen) = 'T' AND UPPER(h.smoke) = 'T'
order by h.hotelRegistDate desc
